// Parse competitor results from both Perplexity searches
const items = $input.all();
const allCompetitors = [];

for (const item of items) {
  try {
    // Native Perplexity node returns choices[0].message.content
    const content = item.json.choices?.[0]?.message?.content || '';
    // Extract JSON array from response
    const jsonMatch = content.match(/\[.*\]/s);
    if (jsonMatch) {
      const competitors = JSON.parse(jsonMatch[0]);
      allCompetitors.push(...competitors);
    }
  } catch (e) {
    console.log('Parse error:', e.message);
  }
}

// Deduplicate by name (case insensitive)
const seen = new Set();
const uniqueCompetitors = allCompetitors.filter(c => {
  const key = c.name.toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
}).slice(0, 3); // Take top 3

// Return each competitor as separate item for loop processing
return uniqueCompetitors.map(c => ({
  json: {
    competitorName: c.name,
    competitorUrl: c.url,
    // Carry forward original form data
    ideaName: $('Idea Input Form').first().json['Idea Name'],
    ideaSummary: $('Idea Input Form').first().json['Idea Summary'],
    targetIndustry: $('Idea Input Form').first().json['Target Industry'],
    targetAudience: $('Idea Input Form').first().json['Target Audience'],
    pricingThoughts: $('Idea Input Form').first().json['Initial Pricing Thoughts'] || '',
    knownCompetitors: $('Idea Input Form').first().json['Known Competitors'] || ''
  }
}));

// Aggregate all research for this competitor
const loopItem = $('Loop Over Competitors').first().json;
const pricingData = $('Research Pricing').first().json;
const featuresData = $('Research Features').first().json;
const weaknessesData = $('Research Weaknesses').first().json;

const extractContent = (data) => {
  // Native Perplexity node returns choices[0].message.content
  return data?.choices?.[0]?.message?.content || 'No data available';
};

return [{
  json: {
    competitorName: loopItem.competitorName,
    competitorUrl: loopItem.competitorUrl,
    pricing: extractContent(pricingData),
    features: extractContent(featuresData),
    weaknesses: extractContent(weaknessesData),
    // Carry forward original data
    ideaName: loopItem.ideaName,
    ideaSummary: loopItem.ideaSummary,
    targetIndustry: loopItem.targetIndustry,
    targetAudience: loopItem.targetAudience,
    pricingThoughts: loopItem.pricingThoughts,
    knownCompetitors: loopItem.knownCompetitors
  }
}];

// Collect all competitor research from loop iterations
// This node runs when loop is complete - use context to get all items

// Get all items from Aggregate Research across all loop iterations
const allItems = [];
const context = $getWorkflowStaticData('global');

// Try to get items from the Aggregate Research node
try {
  const aggregateItems = $('Aggregate Research').all();
  for (const item of aggregateItems) {
    allItems.push(item.json);
  }
} catch (e) {
  // Fallback: try to get from context
}

// If no items found, check if we have any data
if (allItems.length === 0) {
  return [{ json: { error: 'No competitor research found', competitors: [] } }];
}

// Compile all research into single object
const competitors = allItems.map(item => ({
  name: item.competitorName,
  url: item.competitorUrl,
  pricing: item.pricing,
  features: item.features,
  weaknesses: item.weaknesses
}));

// Get original form data from first item
const firstItem = allItems[0] || {};

return [{
  json: {
    ideaName: firstItem.ideaName,
    ideaSummary: firstItem.ideaSummary,
    targetIndustry: firstItem.targetIndustry,
    targetAudience: firstItem.targetAudience,
    pricingThoughts: firstItem.pricingThoughts,
    knownCompetitors: firstItem.knownCompetitors,
    competitors: competitors,
    researchCompiled: competitors.map(c => 
      `## ${c.name}\nURL: ${c.url}\n\n### Pricing\n${c.pricing}\n\n### Features\n${c.features}\n\n### Weaknesses\n${c.weaknesses}`
    ).join('\n\n---\n\n')
  }
}];

// Extract the analysis content from native Anthropic node response
const response = $input.first().json;

// Native Anthropic node returns content array: { content: [{ type: 'text', text: '...' }] }
let analysisContent = '';

if (response.content && Array.isArray(response.content)) {
  // Extract text from content array
  analysisContent = response.content
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('\n');
} else if (response.text) {
  // Fallback for simplified output
  analysisContent = response.text;
} else if (response.message) {
  // Another fallback
  analysisContent = response.message;
}

// Get original data from Collect All Research
let originalData = {};
try {
  originalData = $('Collect All Research').first().json;
} catch (e) {
  originalData = { ideaName: 'Unknown', competitors: [] };
}

return [{
  json: {
    ideaName: originalData.ideaName,
    markdownContent: analysisContent,
    competitors: originalData.competitors
  }
}];
